package org.dromara.sports.event.ai;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.dromara.common.core.enums.UserType;
import org.dromara.common.core.exception.ServiceException;
import org.dromara.common.satoken.utils.LoginHelper;
import org.dromara.sports.api.*;
import org.dromara.sports.event.domain.SportsAiTask;
import org.dromara.sports.event.mapper.SportsAiTaskMapper;
import org.dromara.sports.event.service.EventPublicationService;
import org.dromara.sports.event.service.EventPublicationService.AiDraftState;
import org.dromara.sports.event.ai.SportsEventRunAiTaskService.*;
import org.junit.jupiter.api.Tag;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.*;
import java.util.*;
import java.math.BigDecimal;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Function;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Dedicated UI draft continuation with mocked table contracts; does not assert actual database rollback/concurrency. */
@Tag("local")
class AiCreatedDraftContinuationTest {
    final Map<Class<?>,Object> deps=new HashMap<>();final ObjectMapper json=new ObjectMapper();final SportsEventRunAiTaskService service=create();
    <T>T dep(Class<T> type){return type.cast(deps.get(type));}
    SportsEventRunAiTaskService create(){try{var c=SportsEventRunAiTaskService.class.getDeclaredConstructors()[0];return (SportsEventRunAiTaskService)c.newInstance(Arrays.stream(c.getParameterTypes()).map(type->{Object value=type==ObjectMapper.class?json:mock(type);deps.put(type,value);return value;}).toArray());}catch(Exception e){throw new AssertionError(e);}}
    List<CompetitionSetupApi.DraftUnit> units(){return List.of(new CompetitionSetupApi.DraftUnit(801L,"单打","individual",1,1,8),new CompetitionSetupApi.DraftUnit(802L,"双打","pair",2,2,4));}
    List<FeeApi.PublicUnitPrice> prices(String amount){return List.of(new FeeApi.PublicUnitPrice(801L,"单打",new BigDecimal(amount),"event",null),new FeeApi.PublicUnitPrice(802L,"双打",new BigDecimal(amount),"event",null));}
    AiDraftState state(int version){var card=mock(EventPublicationService.EventCard.class);when(card.id()).thenReturn(902L);when(card.name()).thenReturn("原赛事");when(card.registrationReview()).thenReturn("manual");when(card.declarationText()).thenReturn("本人原文声明");when(card.publicationStatus()).thenReturn("draft");when(card.holdingStatus()).thenReturn("normal");when(card.bannerFileId()).thenReturn(701L);when(card.rulesFileId()).thenReturn(702L);when(card.noticeText()).thenReturn("现有须知");when(card.routeText()).thenReturn("现有路线");when(card.declarationAckRequired()).thenReturn(true);return new AiDraftState(card,version,true);}
    SportsAiTask task(AiDraftState state){
        var task=new SportsAiTask();task.setId(1001L);task.setTenantId("fixture");task.setOrganizationId(601L);task.setInitiatorAccountId(301L);task.setStatus("CREATED");task.setResultObjectId(902L);task.setVersion(7);task.setProviderConsent(true);task.setProviderName("deepseek");
        var proposal=json.createObjectNode();var event=proposal.putObject("event");
        event.putObject("name").put("value","原赛事").put("status","filled");event.putObject("registrationReview").put("value","manual").put("status","filled");var declaration=event.putObject("declarationText").put("value","本人原文声明").put("status","filled");declaration.putArray("sources").addObject().put("quote","本人原文声明");
        var rows=proposal.putArray("units");for(var unit:units()){var row=rows.addObject().put("createdUnitId",Long.toString(unit.unitId()));row.putObject("name").put("value",unit.name()).put("status","filled");row.putObject("entryType").put("value",unit.entryType()).put("status","filled");row.putObject("minMembers").put("value",unit.minMembers());row.putObject("maxMembers").put("value",unit.maxMembers());row.putObject("limitCount").put("value",unit.limitCount());row.putObject("feeAmount").put("value","100").put("status","filled");row.putObject("feeBasis").put("value","order").put("status","filled");}
        task.setProposal(proposal.toString());try{var method=SportsEventRunAiTaskService.class.getDeclaredMethod("bindCreatedBaseline",SportsAiTask.class,ObjectNode.class,AiDraftState.class,boolean.class);method.setAccessible(true);method.invoke(service,task,proposal,state,true);}catch(Exception e){throw new AssertionError(e);}
        proposal.put("createdDirty",false);task.setProposal(proposal.toString());task.setConfirmKey("original-created");return task;
    }
    void session(java.util.function.BiConsumer<SportsAiTask,AtomicReference<AiDraftState>> test){
        var current=new AtomicReference<>(state(2));when(dep(CompetitionSetupApi.class).currentDraftUnits(902L)).thenReturn(units());when(dep(FeeApi.class).publicUnitPrices("fixture",902L)).thenReturn(prices("100"));
        var task=task(current.get());when(dep(SportsAiTaskMapper.class).selectById(1001L)).thenReturn(task);when(dep(SportsAiTaskMapper.class).updateById(any(SportsAiTask.class))).thenReturn(1);
        when(dep(PlatformTransactionManager.class).getTransaction(any(TransactionDefinition.class))).thenReturn(mock(TransactionStatus.class));when(dep(OrganizationSessionApi.class).managedOrganization(201L)).thenReturn(Optional.of(new OrganizationSessionApi.ManagedOrganization(601L,"合成组织","fixture",301L)));when(dep(OrganizationQualificationApi.class).hasStaffAction("fixture",601L,301L,"payment")).thenReturn(true);
        when(dep(EventPublicationService.class).aiDraftState(902L)).thenAnswer(call->current.get());when(dep(EventPublicationService.class).withUnusedAiDraft(eq(902L),any())).thenAnswer(call->((Function<AiDraftState,Object>)call.getArgument(1)).apply(current.get()));when(dep(EventPublicationService.class).update(eq(902L),any())).thenAnswer(call->{current.set(state(current.get().version()+1));return current.get().event();});
        try(var login=mockStatic(LoginHelper.class)){login.when(LoginHelper::isLogin).thenReturn(true);login.when(LoginHelper::getUserType).thenReturn(UserType.SYS_USER);login.when(LoginHelper::getUserId).thenReturn(201L);login.when(LoginHelper::getTenantId).thenReturn("fixture");test.accept(task,current);}
    }
    @Test void ordinaryChatChangesOnlyTheExistingCandidateAndKeepsItsIdentity(){session((task,state)->{var reply=service.talk(1001L,new TalkRequest("全部项目120元",7,null));assertEquals("update",reply.action());assertEquals(902L,reply.eventId());assertFalse(reply.created());assertEquals("CREATED",task.getStatus());try{var after=json.readTree(task.getProposal());assertTrue(after.path("createdDirty").asBoolean());assertEquals("120",after.path("units").get(1).path("feeAmount").path("value").asText());assertEquals("802",after.path("units").get(1).path("createdUnitId").asText());}catch(Exception e){throw new AssertionError(e);}});verify(dep(EventPublicationService.class),never()).create(any());verify(dep(EventPublicationService.class),never()).update(anyLong(),any());verify(dep(FeeApi.class),never()).reviseUnusedDraftPolicy(anyString(),anyLong(),anyLong(),any());}
    @Test void saveUpdatesOriginalEventAndProjectsAndPreservesExistingMaterials(){session((task,state)->{var patch=json.createArrayNode();patch.addObject().put("feeAmount","120");patch.addObject().put("feeAmount","120");service.editCandidate(1001L,new CandidateEdit(7,json.createObjectNode().put("name","更新后赛事"),null,patch));try{assertFalse(json.readTree(task.getProposal()).path("createdDirty").asBoolean());assertEquals(3,json.readTree(task.getProposal()).path("createdEventVersion").asInt());}catch(Exception e){throw new AssertionError(e);}});verify(dep(EventPublicationService.class),never()).create(any());var draft=org.mockito.ArgumentCaptor.forClass(EventPublicationService.EventDraft.class);verify(dep(EventPublicationService.class)).update(eq(902L),draft.capture());assertEquals("更新后赛事",draft.getValue().name());assertEquals(701L,draft.getValue().bannerFileId());assertEquals(702L,draft.getValue().rulesFileId());assertEquals("现有须知",draft.getValue().noticeText());assertEquals("现有路线",draft.getValue().routeText());assertTrue(draft.getValue().declarationAckRequired());verify(dep(CompetitionSetupApi.class)).updateUnusedDraftUnit(902L,801L,"单打","individual",1,1,8);verify(dep(FeeApi.class)).reviseUnusedDraftPolicy("fixture",902L,802L,new BigDecimal("120.00"));verifyNoInteractions(dep(StoredObjectApi.class));}
    @Test void externalEventRevisionRejectsBeforeAnyBusinessWrite(){session((task,state)->{state.set(state(3));assertThrows(ServiceException.class,()->service.editCandidate(1001L,new CandidateEdit(7,json.createObjectNode().put("name","旧窗口"),null,null)));});verify(dep(EventPublicationService.class),never()).update(anyLong(),any());verify(dep(CompetitionSetupApi.class),never()).updateUnusedDraftUnit(anyLong(),anyLong(),anyString(),anyString(),any(),any(),anyInt());}
    @Test void externalFeeChangeRejectsEvenWhenEventVersionHasNotChanged(){session((task,state)->{when(dep(FeeApi.class).publicUnitPrices("fixture",902L)).thenReturn(prices("110"));assertThrows(ServiceException.class,()->service.editCandidate(1001L,new CandidateEdit(7,json.createObjectNode().put("name","旧窗口"),null,null)));});verify(dep(EventPublicationService.class),never()).update(anyLong(),any());}
    @Test void publishChatIsAnIntentAndRequiresAnActualPreviewConfirmation(){session((task,state)->{var reply=service.talk(1001L,new TalkRequest("发布赛事",7,null));assertEquals("publish",reply.action());assertEquals(902L,reply.eventId());assertFalse(reply.created());});verify(dep(EventPublicationService.class),never()).create(any());verify(dep(EventPublicationService.class),never()).update(anyLong(),any());verify(dep(EventPublicationService.class),never()).publish(anyLong(),anyString(),anyBoolean(),any(),any(),any(),any());}
    @Test void publishedActualStateStopsContinuationAndHidesEditableForm(){session((task,state)->{var card=mock(EventPublicationService.EventCard.class);when(card.publicationStatus()).thenReturn("published");when(card.holdingStatus()).thenReturn("normal");state.set(new AiDraftState(card,3,false));assertThrows(ServiceException.class,()->service.talk(1001L,new TalkRequest("全部项目120元",7,null)));var view=service.get(1001L);assertTrue(view.published());assertFalse(view.draftEditable());assertEquals("published",view.eventStatus());});}
    @Test void stalePendingChatCannotEvenStartTheModelOrCandidateWrite(){session((task,state)->{task.setStatus("PENDING_CONFIRMATION");assertThrows(ServiceException.class,()->service.talk(1001L,new TalkRequest("全部项目120元",6,null)));});verifyNoInteractions(dep(SportsEventCallAiGatewayClient.class));verify(dep(SportsAiTaskMapper.class),never()).updateById(any(SportsAiTask.class));}
    @Test void legacyCreatedDraftMustBeExplicitlyRereadBeforeItCanOverwriteAnything(){session((task,state)->{try{var old=(ObjectNode)json.readTree(task.getProposal());old.remove("createdEventVersion");old.remove("createdCatalogSnapshot");task.setProposal(old.toString());task.setConfirmKey(null);var error=assertThrows(ServiceException.class,()->service.editCandidate(1001L,new CandidateEdit(7,json.createObjectNode().put("name","不应覆盖"),null,null)));assertTrue(error.getMessage().contains("读取赛事当前内容"));}catch(java.io.IOException e){throw new AssertionError(e);}});verify(dep(EventPublicationService.class),never()).update(anyLong(),any());verify(dep(SportsAiTaskMapper.class),never()).updateById(any(SportsAiTask.class));}
    @Test void explicitRereadAdoptsAllActualFieldsAndPricesAndKeepsOneBoundedPreviousCandidate(){session((task,state)->{try{
        var old=(ObjectNode)json.readTree(task.getProposal());old.remove("createdEventVersion");old.remove("createdCatalogSnapshot");old.putObject("previousCreatedCandidate").put("notRecursive","older");old.putObject("cover").put("fileId","original-source");task.setProposal(old.toString());task.setExtraction("immutable-original-source");
        var actual=state(4);when(actual.event().name()).thenReturn("实际最新赛事");when(actual.event().location()).thenReturn("实际最新场馆");when(actual.event().contactName()).thenReturn("实际联系人");when(actual.event().contactMethod()).thenReturn("实际渠道");when(actual.event().refundTerms()).thenReturn("实际退改说明");var opens=java.time.OffsetDateTime.now().withOffsetSameInstant(java.time.ZoneOffset.ofHours(8)).plusDays(10).withNano(0);when(actual.event().registrationOpensAt()).thenReturn(opens);when(actual.event().registrationClosesAt()).thenReturn(opens.plusDays(1));when(actual.event().startsAt()).thenReturn(opens.plusDays(2));when(actual.event().endsAt()).thenReturn(opens.plusDays(3));state.set(actual);when(dep(FeeApi.class).publicUnitPrices("fixture",902L)).thenReturn(prices("110"));
        var reply=service.talk(1001L,new TalkRequest("重新读取赛事草稿",7,null));assertEquals(902L,reply.eventId());assertEquals("update",reply.action());assertFalse(reply.created());var after=json.readTree(task.getProposal());assertEquals("实际最新赛事",after.at("/event/name/value").asText());assertEquals("实际最新场馆",after.at("/event/location/value").asText());assertEquals("实际联系人",after.at("/event/contactName/value").asText());assertEquals("实际渠道",after.at("/event/contactMethod/value").asText());assertEquals("实际退改说明",after.at("/event/refundTerms/value").asText());assertEquals(opens.plusDays(3).toString(),after.at("/event/endsAt/value").asText());assertEquals("110",after.at("/units/1/feeAmount/value").asText());assertEquals("802",after.at("/units/1/createdUnitId").asText());assertEquals(4,after.path("createdEventVersion").asInt());assertFalse(after.path("createdDirty").asBoolean());assertEquals("原赛事",after.at("/previousCreatedCandidate/event/name/value").asText());assertEquals("original-source",after.at("/previousCreatedCandidate/cover/fileId").asText());assertFalse(after.path("previousCreatedCandidate").has("previousCreatedCandidate"));assertFalse(after.has("cover"));assertEquals("immutable-original-source",task.getExtraction());
        service.editCandidate(1001L,new CandidateEdit(7,json.createObjectNode().put("name","重读后继续修改"),null,null));
    }catch(java.io.IOException e){throw new AssertionError(e);}});verify(dep(EventPublicationService.class)).update(eq(902L),any());verify(dep(EventPublicationService.class),never()).create(any());}
    @Test void rereadRejectsAStaleTaskRevisionBeforeReplacingTheCandidate(){session((task,state)->{String before=task.getProposal();assertThrows(ServiceException.class,()->service.talk(1001L,new TalkRequest("重新读取赛事草稿",6,null)));assertEquals(before,task.getProposal());});verify(dep(SportsAiTaskMapper.class),never()).updateById(any(SportsAiTask.class));}
    @Test void rereadCannotBypassActualDraftHistoryOrPublicationGuard(){session((task,state)->{when(dep(EventPublicationService.class).withUnusedAiDraft(eq(902L),any())).thenThrow(new ServiceException("已有报名，不能修改",409));String before=task.getProposal();assertThrows(ServiceException.class,()->service.talk(1001L,new TalkRequest("重新读取赛事草稿",7,null)));assertEquals(before,task.getProposal());});verify(dep(SportsAiTaskMapper.class),never()).updateById(any(SportsAiTask.class));}
}
